return {
  [ [[v5748eaic9tph]] ] = { t = [[百战雄主的武具]], q = [=[百战雄主的武具免疫[[破损]]状态，这究竟是什么意思？它永远不会被摧毁吗？我能不能反复使用那些以弄坏你的武器来换取好处的能力？]=], a = [[在这个特例中，它的含义与通常所说的“免疫”略有不同：它意味着武具即使变成破损状态也不会遭受任何减值。它仍然可以获得破损状态，并且在判定那些会因你处于破损状态而升级的效果（例如会给予破损状态、或在目标已具有破损状态时将其摧毁的效果）时，它仍被视为具有破损状态。和通常一样，如果一件武器已经具有破损状态，你就不能对它使用会令武器破损的效果。下一版勘误中会加入相应的说明。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tph]], cat = [[FAQ]], ai = true, pages = { [[百战雄主]] } },
  [ [[v5748eaic9tps]] ] = { t = [[唤魂师与降咒]], q = [=[[[唤魂师]]获得的[[降咒]]被同时列为3环和4环法术，哪一个才对？]=], a = [[它应当是3环法术。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tps]], cat = [[FAQ]], ai = false, pages = { [[降咒]] } },
  [ [[v5748eaic9tpj]] ] = { t = [[情绪成分]], q = [=[诸如[[威吓]]之类的效果造成的[[战栗]]状态，在阻止具有情绪成分的法术时，算不算“具有恐惧描述符的效果”？]=], a = [=[算。原文本应写作“恐惧效果”；对于大多数描述符来说，这两种措辞有时是可以互换使用的。举例来说，一项保护你不受具有魅惑描述符的效果影响的能力，通常也会保护你免受[[鹰身女妖]]之歌（它是一种魅惑效果）的影响。]=], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpj]], cat = [[FAQ]], ai = true, pages = { [[异能法术]] } },
  [ [[v5748eaic9tpk]] ] = { t = [[情感障碍]], q = [[情感障碍应该具有情绪描述符吗？法术说明里写了它有，但这样它就成了一个非无害的情绪效果，会阻止所有施法。]], a = [[它不应该具有情绪描述符。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpk]], cat = [[FAQ]], ai = true, pages = { [[情感障碍]] } },
  [ [[v5748eaic9tpi]] ] = { t = [[情感导体与守护灵]], q = [=[[[情感导体]]中守护灵的3环法术列为[[治疗轻伤]]，它应该是[[治疗重伤]]吗？]=], a = [[是的，应该是治疗重伤。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpi]], cat = [[FAQ]], ai = true, pages = { [[情感导体]] } },
  [ [[v5748eaic9tpm]] ] = { t = [[操念使天赋职业奖励与元素满溢]], q = [[精灵的天赋职业奖励提到它在元素满溢生效时才适用，而矮人和半兽人的却没有这样说。它们是不是也应当只在元素满溢生效时适用？]], a = [[是的，它们两个都应当像精灵的天赋职业奖励一样，只在元素满溢生效时适用。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpm]], cat = [[FAQ]], ai = true, pages = { [[操念使]] } },
  [ [[v5748eaic9tpl]] ] = { t = [[操念使念力凝聚]], q = [=[我知道念力凝聚只能用于[[念袭]]类[[原力]]，但在那些会给念袭原力增加成本的东西当中，哪些可以用念力凝聚来减少？注能的说明里写得很清楚，其他的则没有说明。]=], a = [=[你可以降低注能、超念，以及使用万力全能施放自己并不具备的念袭时所需的额外1点超载。这些全都会增加念袭的消耗。你仍然不能降低[[通用原力]]的消耗，包括使用万力全能替换通用原力时的额外超载消耗，除非你改用储念器。]=], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpl]], cat = [[FAQ]], ai = false, pages = { [[操念使]] } },
  [ [[v5748eaic9tpq]] ] = { t = [[通灵者的偏好降灵区域]], q = [[通灵者职业说明英灵可以在任何合适的地点降灵，而不只限于偏好降灵区域列表上的那些，但这是真的吗？还是说我只能在其中一个偏好区域降灵？]], a = [[正如职业所述，你可以在任何合适的地点降灵，偏好区域只是一个起点。有时你可能无法接触到全部六种英灵，但无论是PC还是NPC，只要通灵者能在某个英灵与某处他能找到、甚至能自己布置出来的地点之间想出一个合理的概念联系，通常就应当能够接触到那个英灵。举例来说，通灵者可以去猎一头鹿，再以那处猎场为地点，降下一位传奇猎手的勇士英灵。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpq]], cat = [[FAQ]], ai = false, pages = { [[通灵者]] } },
  [ [[v5748eaic9tpp]] ] = { t = [[脑力屏蔽]], q = [[法术说明里的“激活”一词，是只涵盖专长，还是也适用于特异、超自然和类法术能力？]], a = [[它应当适用于它们全部。这个法术只会阻止目标使用主动能力，对被动能力完全不起作用。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpp]], cat = [[FAQ]], ai = true, pages = { [[脑力屏蔽]] } },
  [ [[v5748eaic9tpu-2]] ] = { t = [[异能者与神威如狱]], q = [=[和谐境界的[[异能者]]将神威如狱作为9环境界法术获得，但它在异能者法术列表中却是4环法术。对异能者来说它应该是9环法术吗？]=], a = [[是的，它应该是9环法术。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpu]], cat = [[FAQ]], ai = true, pages = { [[神威如狱]], [[精神境界/和谐]] } },
  [ [[v5748eaic9tpu]] ] = { t = [[心灵血统术士]], q = [=[心灵血统的血统奥秘把心灵血统的法术从奥术法术改为心灵法术。这显然意味着心灵血统[[术士]]符合那些要求“具有施放心灵法术的能力”的能力，而不符合要求“具有施放奥术法术的能力”的能力；但对于要求“奥术施法职业”的能力呢，比如[[半精灵]]的奥术训练——选择职业的时候，你可能还没有获得术士等级、也没有选择心灵血统？这是否普遍适用于那些在奥术、神术和心灵之间改变你施法类型的能力？]=], a = [=[这个组合会引出一种复杂的互动：在半精灵这项能力问世的时候，“奥术施法职业”一词并无歧义，因为变体职业当时还是新事物，距离出现能改变角色所施放法术类型的变体职业或血统还有好几年。本质上，选择了术士的、具有奥术训练能力的半精灵，选择的是“奥术施法职业术士”。如果她随后获得心灵血统术士的等级，她获得的就不是自己[[天赋职业]]的等级。不过，这项能力仍会有一点小小的效果：由于她在天赋职业上没有等级，她仍然算作1级的“奥术施法术士”，因而可以相应地使用奥术卷轴（而通常情况下，即便卷轴上的法术在她的法术列表上，她也需要使用[[使用魔法装置]]才能使用奥术或神术卷轴）。

据我们所知，这是第一次需要用到这条原则，但它同样适用于其他会改变你魔法类型的情形，甚至不限于此：例如，某项替换种族特性把你的天赋职业奖励限定为“一个授予重甲擅长的职业”，而你选了[[战士]]，但随后你获得的战士等级用的是一个替换掉了重甲擅长的变体职业，那么你选择的这个战士变体职业就不算你的天赋职业。

这条原则也可以反过来用。如果半精灵的那项能力要求你选择的是心灵施法职业而不是奥术施法职业，你可以选择术士，并打算以后选择心灵血统；但在那种情况下，这项种族特性要等到你真正取得了心灵血统术士的等级之后才会起作用，因为术士在没有心灵血统时本身并不是心灵施法职业。]=], book = [[异能冒险]], date = [[2016/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpu]], cat = [[FAQ]], ai = true, pages = { [[术士血统/心灵血统]], [[半精灵]] } },
  [ [[v5748eaic9tpr]] ] = { t = [[魅影与护甲]], q = [=[[[唤魂师]]职业中有两处规则互相冲突：一处说[[魅影]]可以穿护甲，另一处说它们不能。哪个是对的？]=], a = [[魅影不能穿护甲；那句话本意是说它们可以穿戴其他魔法物品。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpr]], cat = [[FAQ]], ai = false, pages = { [[唤魂师]] } },
  [ [[v5748eaic9tpn]] ] = { t = [[念动遁形]], q = [=[这个原力的说明里有很多地方似乎暗示我只能对自己使用，但它又说效果如同[[隐形术]]，而隐形术并非只能作用于自身。到底哪种说法是对的？]=], a = [[你只能对自己使用。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpn]], cat = [[FAQ]], ai = false, pages = { [[念动遁形]] } },
  [ [[v5748eaic9tpo]] ] = { t = [[迸发注能]], q = [[这个注能似乎漏掉了闪电念袭，把它列为关联念袭之一。这是有意为之的吗？]], a = [[闪电念袭应当被包含在内。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpo]], cat = [[FAQ]], ai = true, pages = { [[迸发]] } },
  [ [[v5748eaic9tpt]] ] = { t = [[感知者与武器训练1]], q = [=[感知者没有提到替换[[战士#武器训练|武器训练]]1，但它在5级（也就是武器训练1的获得等级）获得了一项极为相似的能力。它是不是也应当替换掉武器训练1？]=], a = [[是的。这一点将在下一版勘误中体现。]], book = [[异能冒险]], date = [[2015/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h5#v5748eaic9tpt]], cat = [[FAQ]], ai = false, pages = { [[感知者]] } },
